const dropdownAnimation = trigger('dropdownAnimation', [
    transition(':enter', [
        style({ height: '0', opacity: 0, overflow: 'hidden' }),
        animate('500ms ease-out', style({ height: '100%', opacity: 1 })),
    ]),
    transition(':leave', [
        style({
            height: '100%',
            maxHeight: '100%',
            opacity: 1,
            overflow: 'hidden',
        }),
        animate('500ms ease-in', style({ height: '0', maxHeight: '0', opacity: 0 })),
    ]),
]);
const expandingOuterAnimation = trigger('expandingOuterAnimation', [
    transition('leave => enter', [
        style({ height: '0' }),
        animate('200ms ease-out', style({ height: '*' })),
    ]),
    transition('enter => leave', [
        animate('200ms ease-in', style({ height: '0', overflow: 'hidden' })),
    ]),
]);
